diff --git a/src/main/java/org/jsoup/nodes/XmlDeclaration.java b/src/main/java/org/jsoup/nodes/XmlDeclaration.java
index 24a9f164..4b7f89f9 100644
--- a/src/main/java/org/jsoup/nodes/XmlDeclaration.java
