@@ -21,8 +21,33 @@ public class XmlDeclaration extends Node {
     public XmlDeclaration(String name, String baseUri, boolean isProcessingInstruction) {
         super(baseUri);
         Validate.notNull(name);
-        this.name = name;
+
+        // Strip trailing ? if present
+        String cleanName = name;
+        if (cleanName.endsWith("?")) {
+            cleanName = cleanName.substring(0, cleanName.length() - 1).trim();
+        }
+
+        // Parse the declaration name and attributes
+        String[] parts = cleanName.split("\\s+", 2);
+        this.name = parts[0];
         this.isProcessingInstruction = isProcessingInstruction;
+
+        // Parse attributes if present
+        if (parts.length > 1) {
+            parseAttributes(parts[1]);
+        }
+    }
+
+    private void parseAttributes(String attrString) {
+        // Simple parser for attributes in the form: version='1' encoding='UTF-8'
+        java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("(\\w+)\\s*=\\s*['\"]([^'\"]*)['\"]");
+        java.util.regex.Matcher matcher = pattern.matcher(attrString);
+        while (matcher.find()) {
+            String key = matcher.group(1);
+            String value = matcher.group(2);
+            attr(key, value);
+        }
     }

     public String nodeName() {
@@ -44,15 +69,15 @@ public class XmlDeclaration extends Node {
      */
     public String getWholeDeclaration() {
         final String decl = this.name;
-        if(decl.equals("xml") && attributes.size() > 1 ) {
-            StringBuilder sb = new StringBuilder(decl);
-            final String version = attributes.get("version");
-            if( version != null ) {
-                sb.append(" version=\"").append(version).append("\"");
-            }
-            final String encoding = attributes.get("encoding");
