-                sb.append(" encoding=\"").append(encoding).append("\"");
+        if(decl.equals("xml") && attributes.size() > 0 ) {
+            StringBuilder sb = new StringBuilder();
+            boolean first = true;
+            for (Attribute attr : attributes) {
+                if (!first) {
+                    sb.append(" ");
+                }
+                sb.append(attr.getKey()).append("=\"").append(attr.getValue()).append("\"");
+                first = false;
             }
             return sb.toString();
         }
@@ -65,8 +90,16 @@ public class XmlDeclaration extends Node {
         accum
             .append("<")
             .append(isProcessingInstruction ? "!" : "?")
-                .append(getWholeDeclaration())
-            .append(">");
+            .append(name);
+
+        if (name.equals("xml") && attributes.size() > 0) {
+            accum.append(" ");
+            accum.append(getWholeDeclaration());
+        }
+
+        if (!isProcessingInstruction)
+            accum.append("?");
+        accum.append(">");
     }

